import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { authAPI } from '../services/api';

function Login() {
  const [formData, setFormData] = useState({ 
    email: '', 
    password: '' 
  });
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ 
      ...prev, 
      [name]: value.trim() 
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    
    // Validate mạnh mẽ
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      setError('Email không hợp lệ');
      return;
    }

    if (formData.password.length < 6) {
      setError('Mật khẩu phải có ít nhất 6 ký tự');
      return;
    }

    setIsLoading(true);

    try {
      console.log('Sending login request with:', formData); // Debug log
      
      // Gửi cả email và usernameOrEmail để phù hợp với backend
      const loginData = {
        usernameOrEmail: formData.email,
        email: formData.email,
        password: formData.password
      };

      const response = await authAPI.login(loginData);
      console.log('Login response:', response); // Debug log
      
      if (!response?.success || !response?.token) {
        throw new Error(response?.message || 'Đăng nhập không thành công');
      }

      // Lưu thông tin người dùng
      localStorage.setItem('token', response.token);
      if (response.user) {
        localStorage.setItem('user', JSON.stringify(response.user));
      }
      
      // Chuyển hướng và thay thế history
      navigate('/', { replace: true });

    } catch (err) {
      console.error('Login Error Details:', {
        error: err,
        response: err.response?.data
      });
      
      // Xử lý lỗi từ server chi tiết hơn
      let errorMessage = 'Đăng nhập thất bại. Vui lòng thử lại';
      
      if (err.response?.data) {
        const serverError = err.response.data;
        
        // Xử lý cả object errors và message thông thường
        if (serverError.errors) {
          errorMessage = Object.entries(serverError.errors)
            .map(([field, errors]) => `${field}: ${Array.isArray(errors) ? errors.join(', ') : errors}`)
            .join('\n');
        } else if (serverError.message) {
          errorMessage = serverError.message;
        }
      } else if (err.message) {
        errorMessage = err.message;
      }
      
      setError(errorMessage);
      
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="auth-container">
      <h2>Đăng Nhập</h2>
      {error && (
        <div className="error-message">
          {error.split('\n').map((line, i) => (
            <p key={i} style={{ color: 'red', margin: '4px 0' }}>{line}</p>
          ))}
        </div>
      )}
      
      <form onSubmit={handleSubmit} noValidate>
        <div className="form-group">
          <label htmlFor="email">Email:</label>
          <input
            id="email"
            type="email"
            name="email"
            value={formData.email}
            onChange={handleChange}
            required
            autoComplete="username"
            aria-describedby="email-error"
            style={{ width: '100%', padding: '8px' }}
          />
        </div>
        
        <div className="form-group">
          <label htmlFor="password">Mật khẩu:</label>
          <input
            id="password"
            type="password"
            name="password"
            value={formData.password}
            onChange={handleChange}
            required
            minLength="6"
            autoComplete="current-password"
            aria-describedby="password-error"
            style={{ width: '100%', padding: '8px' }}
          />
        </div>
        
        <button 
          type="submit" 
          disabled={isLoading}
          className="login-button"
          aria-busy={isLoading}
          style={{
            width: '100%',
            padding: '10px',
            backgroundColor: isLoading ? '#ccc' : '#007bff',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer'
          }}
        >
          {isLoading ? 'Đang đăng nhập...' : 'Đăng Nhập'}
        </button>
      </form>
      
      <p className="register-link" style={{ marginTop: '16px', textAlign: 'center' }}>
        Chưa có tài khoản? <a href="/register" style={{ color: '#007bff' }}>Đăng ký ngay</a>
      </p>
    </div>
  );
}

export default Login;
